     /// an error if the chassis has no SFP there.
     pub fn sfp(&self, index: usize) -> Result<Sfp> {
         Python::with_gil(|py| {
             let obj = self.chassis.bind(py).call_method1("get_sfp", (index,))?;
             if obj.is_none() {
                 return Err(BridgeError::Other(format!("no sfp at index {index}")));
             }
             Ok(Sfp {
                 obj: obj.unbind(),
                 index,
             })
         })
     }

