     generic_error_bits = (error_bits & SFP_ERRORS_GENERIC_MASK)
     error_descriptions = []
     if generic_error_bits:
         for error_bit, error_description in SfpBase.SFP_ERROR_BIT_TO_DESCRIPTION_DICT.items():
